1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using Microsoft.Extensions.ML;
4. 
5. var builder = WebApplication.CreateBuilder(args);
6. 
7. var mlContext = new MLContext(seed: 42);
8. var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
9. 
10. // Load and split data
11. var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');
12. var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);
13. 
14. // Build training pipeline
15. var pipeline = mlContext.Transforms.CustomMapping<CustomerData, ChurnLabel>(
16.         (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
17.         contractName: "ChurnMapping")
18.     .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
19.     .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerData.Age)))
20.     .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerData.Income)))
21.     .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerData.PurchaseHistory)))
22.     .Append(mlContext.Transforms.Concatenate("Features",
23.         nameof(CustomerData.Age), nameof(CustomerData.Income), "RegionEncoded", nameof(CustomerData.PurchaseHistory)))
24.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
25.         labelColumnName: "Label", featureColumnName: "Features"));
26. 
27. // Train and evaluate
28. var model = pipeline.Fit(split.TrainSet);
29. var predictions = model.Transform(split.TestSet);
30. 
31. try
32. {
33.     var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
34.     Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, F1: {metrics.F1Score:F4}, Accuracy: {metrics.Accuracy:F4}");
35. }
36. catch (ArgumentOutOfRangeException)
37. {
38.     Console.WriteLine("Model trained — test set too small for meaningful metrics. Add more data for proper evaluation.");
39. }
40. 
41. // Register pooled prediction engine for thread-safe web usage
42. var modelPath = Path.Combine(AppContext.BaseDirectory, "churn_model.zip");
43. mlContext.Model.Save(model, dataView.Schema, modelPath);
44. 
45. builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
46.     .FromFile(modelPath);
47. 
48. var app = builder.Build();
49. 
50. app.MapGet("/", () => "Churn Predictor API — POST to /predict");
51. 
52. app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerData customer) =>
53. {
54.     var prediction = pool.Predict(customer);
55.     return Results.Ok(new
56.     {
57.         willChurn = prediction.PredictedLabel,
58.         probability = prediction.Probability,
59.         score = prediction.Score
60.     });
61. });
62. 
63. app.Run();
